import{_ as a,o as s,c as i,a6 as t}from"./chunks/framework.BBIckNDn.js";const u=JSON.parse('{"title":"第12部 演習 — 判断ガイド","description":"","frontmatter":{"title":"第12部 演習 — 判断ガイド","study":{"source":"C++ Wiki","kind":"演習","status":"既存原稿","summary":"判断フローを「使う」練習です。結論だけでなく、どの質問で分岐したかを言えることが目標です。 次の主張の問題点を、該当する判断ガイドを引いて指摘してください。 「このクラスは500行を超えたので分割すべきだ」"}},"headers":[],"relativePath":"design/decisions/exercises.md","filePath":"design/decisions/exercises.md"}'),r={name:"design/decisions/exercises.md"};function n(d,e,o,l,h,c){return s(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="第12部-演習-—-判断ガイド" tabindex="-1">第12部 演習 — 判断ガイド <a class="header-anchor" href="#第12部-演習-—-判断ガイド" aria-label="Permalink to &quot;第12部 演習 — 判断ガイド&quot;">​</a></h1><p>判断フローを「使う」練習です。結論だけでなく、<strong>どの質問で分岐したか</strong>を言えることが目標です。</p><h2 id="問1-概念確認" tabindex="-1">問1. 概念確認 <a class="header-anchor" href="#問1-概念確認" aria-label="Permalink to &quot;問1. 概念確認&quot;">​</a></h2><p>次の主張の問題点を、該当する判断ガイドを引いて指摘してください。</p><ol><li>「このクラスは500行を超えたので分割すべきだ」</li><li>「将来のために全クラスにインターフェースを切っておいた」</li><li>「イベント駆動にしたので、ダメージ→死亡→ドロップもバスに流した」</li><li>「デバッグビルドで計測したらここが遅かったので最適化した」</li></ol><details><summary>解答</summary><ol><li>分割基準は行数でなく変更理由の数(<a href="/study/design/decisions/split-class.html">クラス分割</a>Q1)。2. 実装1つ・差し替え予定なしの抽象はコストのみ(<a href="/study/design/decisions/create-interface.html">インターフェース</a>Q1〜3)。3. ルールの帰結(順序が仕様)はイベントにしない(<a href="/study/design/decisions/events-di-singleton.html">イベントの判断</a>)。4. デバッグビルドの計測は最適化判断の根拠にならない(Shipping相当で再計測 → <a href="/study/design/decisions/optimize-or-refactor.html">最適化の判断</a>)。</li></ol></details><h2 id="問2-コード読解-判断の復元" tabindex="-1">問2. コード読解(判断の復元) <a class="header-anchor" href="#問2-コード読解-判断の復元" aria-label="Permalink to &quot;問2. コード読解(判断の復元)&quot;">​</a></h2><p>あるコードレビューで「ここはswitchのままでいい」という結論になりました。どんな判断材料が揃っていたと推測できますか。3つ挙げてください。</p><details><summary>解答例</summary><p>(a) 分岐対象の種類が少なく(2〜4)、追加の予定・実績がない(<a href="/study/design/solid/ocp.html">OCP</a>を開く証拠なし)。(b) 同じ分岐が複数関数に複製されていない(1か所に集約済み)。(c) 種類を横断して一覧できる価値がある(バランス確認など)、またはチームがポリモーフィズム版の追跡コストを払いたくない(<a href="/study/design/decisions/abstraction-and-patterns.html">抽象化の判断</a>Q3「簡潔案との比較」)。</p></details><h2 id="問3-設計判断-ケース適用" tabindex="-1">問3. 設計判断(ケース適用) <a class="header-anchor" href="#問3-設計判断-ケース適用" aria-label="Permalink to &quot;問3. 設計判断(ケース適用)&quot;">​</a></h2><p>「ローグライクのアイテム(消費・装備・呪い、200種予定、週次で追加)」について、(a) 構造体かクラスか、(b) 継承かコンポジションか、(c) データ駆動にするか、の3判断をフローに沿って行い、結論と分岐点を記録してください。</p><details><summary>解答の要点</summary><p>(a) アイテム定義(名前・数値・効果リスト)は不変条件のないデータ → struct+public(<a href="/study/design/decisions/cpp-choices.html">構造体かクラスか</a>)。所持インベントリ(個数整合)はclass。(b) 消費/装備/呪いは「特徴の組み合わせ」(呪われた装備)→ コンポジション(効果リスト)(<a href="/study/design/decisions/inheritance-or-composition.html">継承かコンポジションか</a>Q4)。(c) 200種・週次追加は「追加が繰り返される証拠」が最初からある → データ駆動を初期から(<a href="/study/design/case-studies/item-effects.html">アイテム効果</a>の案A)。</p></details><h2 id="問4-設計比較-投資の優先順位" tabindex="-1">問4. 設計比較(投資の優先順位) <a class="header-anchor" href="#問4-設計比較-投資の優先順位" aria-label="Permalink to &quot;問4. 設計比較(投資の優先順位)&quot;">​</a></h2><p>チームに1週間の「改善スプリント」が与えられました。候補: (A) 全域Singletonの3つをDI化 (B) ビルド時間を15分→5分に (C) 神クラスGameManagerの分割 (D) 主要ロジックへのユニットテスト追加。あなたのプロジェクト想定(自由に設定してよい)で優先順位を付け、判断ガイドの語彙で正当化してください。</p><details><summary>解答例(想定: 中規模・週次リリース・テストなし)</summary><p><strong>B → D → C → A</strong>。B: ビルド時間は全員の全作業に掛かる利息で、回収が最速(<a href="/study/design/foundations/tech-debt-and-refactoring.html">技術的負債</a>の「高利息」)。D: テストは今後の全リファクタの前提条件(<a href="/study/design/decisions/optimize-or-refactor.html">リファクタの判断</a>Q3)であり、Cを安全にやるためにも先。C: 触る頻度が高いなら高利息だが、Dなしでは危険。A: Singletonは「テストで差し替えたくなった時」が移行タイミングで、D完了後に痛みが顕在化してからで遅くない(<a href="/study/design/decisions/events-di-singleton.html">Singletonの判断</a>)。<strong>別解も成立する</strong>(Cが毎日の開発を止めているなら最優先)——順位そのものより「利息と前提条件」で語れているかが評価点。</p></details><h2 id="問5-デバッグ問題-判断ミスの事後分析" tabindex="-1">問5. デバッグ問題(判断ミスの事後分析) <a class="header-anchor" href="#問5-デバッグ問題-判断ミスの事後分析" aria-label="Permalink to &quot;問5. デバッグ問題(判断ミスの事後分析)&quot;">​</a></h2><p>「半年前に導入した汎用イベントバスが原因で、不具合調査に毎回半日かかっている」。当時の判断のどこが誤りだった可能性が高いか、<a href="/study/design/decisions/events-di-singleton.html">イベントの判断</a>と<a href="/study/design/decisions/abstraction-and-patterns.html">抽象化の判断</a>のフローで事後分析してください。</p><details><summary>解答の要点</summary><p>可能性1: 破綻シグナルが出る前の導入(「疎結合は良いこと」という一般論での採用 — 治療でなく予防接種)。可能性2: 3分類の無視——ルールの帰結までバスに流し、因果が追えなくなった。可能性3: 導入時に「イベントログ(全発行の記録)」という追跡手段をセットで作らなかった(欠点への手当てなしの採用)。教訓: パターンの採用判断には「その欠点をどう緩和するか」まで含める。</p></details><h2 id="問6-説明問題" tabindex="-1">問6. 説明問題 <a class="header-anchor" href="#問6-説明問題" aria-label="Permalink to &quot;問6. 説明問題&quot;">​</a></h2><p>このWiki全体を貫く「トレードオフで判断する」という姿勢を、後輩への1分間の説明として文章化してください(5文以内)。</p><details><summary>解答例</summary><p>設計の道具(SOLID、パターン、抽象化)は全部「何かを良くする代わりに何かを悪くする」交換であって、無料の正解はない。だから「使うべきか」は道具の知識ではなく、状況の証拠——変更が繰り返されているか、計測で遅いか、後から変えるのが高い決定か——で決める。証拠がないうちは素朴に書き、破綻のシグナルが出たら対応する道具で治す。ただしセーブ形式のような不可逆な決定だけは先に手を打つ。そして選ばなかった案と理由を一行残しておけば、将来の自分たちが再判断できる。</p></details><h2 id="問7-小規模実装問題-判断の実地演習" tabindex="-1">問7. 小規模実装問題(判断の実地演習) <a class="header-anchor" href="#問7-小規模実装問題-判断の実地演習" aria-label="Permalink to &quot;問7. 小規模実装問題(判断の実地演習)&quot;">​</a></h2><p>自分の現行プロジェクト(なければ<a href="/study/design/case-studies/exercises.html">第11部演習の問7</a>のWave Survival)から機能追加を1つ選び、実装<strong>前</strong>に以下を書いてから実装してください。</p><ol><li>適用した判断ガイドと、通った分岐(Q1→Q2→…)</li><li>採用案と、比較した「より素朴な案」</li><li>実装後: 判断は正しかったか、想定と違った点</li></ol><p>この「判断ログ」の習慣がこのWikiの最終目標です。</p><hr><p>前: <a href="/study/design/decisions/optimize-or-refactor.html">最適化・リファクタリングの判断</a> | <a href="/study/design/decisions/">カテゴリ目次</a> | <a href="/study/guide/cpp-index.html">全体目次へ</a></p>',27)])])}const p=a(r,[["render",n]]);export{u as __pageData,p as default};
